import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Play, Pause, SkipBack, SkipForward, Shuffle, Repeat, Volume2, VolumeX, Download, Heart, List, ChevronUp, ChevronDown, Trash2 } from 'lucide-react';
import { usePlayer } from '../../context/PlayerContext';
import { useAuth } from '../../context/AuthContext';
import { recordSongDownload } from '../../lib/statsHelper';
import { Slider } from '../ui/slider';
import { Button } from '../ui/button';
import { toast } from '../../hooks/use-toast';
import { formatDuration } from '../../mock';
import { useMusicFavorite } from '../../hooks/use-music-favorite';
import { supabase } from '../../lib/supabaseClient';

const CreatePlaylistIcon = () => (
  <svg stroke="currentColor" fill="currentColor" strokeWidth="0" viewBox="0 0 24 24" height="1em" width="1em" xmlns="http://www.w3.org/2000/svg">
    <path fill="none" d="M0 0h24v24H0z"></path>
    <path d="M14 10H3v2h11v-2zm0-4H3v2h11V6zm4 8v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zM3 16h7v-2H3v2z"></path>
  </svg>
);

const Player = () => {
  const navigate = useNavigate();
  const {
     currentSong,
     isPlaying,
     currentTime,
     duration,
     volume,
     isShuffle,
     repeatMode,
     togglePlay,
     handleNext,
     handlePrevious,
     seekTo,
     setVolume,
     toggleShuffle,
     toggleRepeat,
     queue,
     clearQueue,
     playSong,
     setIsCompactMode
   } = usePlayer();

  const { isPremium, user } = useAuth();
  const [showQueue, setShowQueue] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [imageError, setImageError] = useState(false);
  const [isCompact, setIsCompact] = useState(false);
  const [createPlaylistOpen, setCreatePlaylistOpen] = useState(false);
  const [playlistData, setPlaylistData] = useState({
    title: '',
    description: '',
    isPublic: false,
    cover: null
  });
  
  // Use music favorite hook
  const { isFavorite, toggleFavorite, loading: favoriteLoading } = useMusicFavorite(currentSong?.id);

  if (!currentSong) return null;

  const cleanTitle = (title) => {
    return title?.replace(/\.mp3$/i, '') || '';
  };

  const handleVolumeChange = (value) => {
    setVolume(value[0]);
    setIsMuted(value[0] === 0);
  };

  const toggleMute = () => {
    if (isMuted) {
      setVolume(0.7);
      setIsMuted(false);
    } else {
      setVolume(0);
      setIsMuted(true);
    }
  };

  const handleCreatePlaylist = () => {
    if (!user) {
      toast({
        title: 'Login Necessário',
        description: 'Faça login para criar uma playlist',
        variant: 'destructive'
      });
      return;
    }
    setCreatePlaylistOpen(true);
  };

  const handleDownload = async () => {
    if (!currentSong?.audioUrl) {
      toast({
        title: 'Download Indisponível',
        description: 'Arquivo não disponível',
        variant: 'destructive'
      });
      return;
    }
    
    toast({
      title: 'Download Iniciado',
      description: `Baixando ${currentSong.title}...`
    });
    
    try {
      // Registrar download da música
      if (currentSong.id) {
        const albumId = currentSong.albumId || currentSong.album_id || currentSong.albumid;
        recordSongDownload(currentSong.id, albumId);
      }

      const response = await fetch(currentSong.audioUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `${currentSong.title}.mp3`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Download error:', error);
      toast({
        title: 'Erro no Download',
        description: 'Não foi possível baixar o arquivo',
        variant: 'destructive'
      });
    }
  };

  const handleFavorite = async () => {
    if (!user) {
      toast({
        title: 'Login Necessário',
        description: 'Faça login para adicionar aos favoritos',
        variant: 'destructive'
      });
      return;
    }
    
    try {
      await toggleFavorite();
      toast({
        title: isFavorite ? 'Removido dos favoritos' : 'Adicionado aos favoritos',
        description: currentSong.title
      });
    } catch (error) {
      toast({
        title: 'Erro',
        description: 'Erro ao atualizar favoritos',
        variant: 'destructive'
      });
    }
  };

  const handleClearQueue = () => {
    clearQueue();
    setShowQueue(false);
    toast({
      title: 'Fila limpa',
      description: 'Todas as músicas foram removidas da fila'
    });
  };

  const handlePlayFromQueue = (song) => {
    playSong(song, queue);
  };

  const progress = duration > 0 ? (currentTime / duration) * 100 : 0;

  // Versão compactada
   if (isCompact) {
     return (
       <div className="fixed bottom-4 right-4 z-50 bg-zinc-900 rounded-lg shadow-2xl p-3 w-64">
         <button
           onClick={() => {
             setIsCompact(false);
             setIsCompactMode(false);
           }}
           className="absolute -top-6 right-2 bg-red-600 px-2 py-1 rounded-t hover:bg-red-700 transition"
           title="Expandir player"
         >
           <ChevronUp className="w-4 h-4 text-white" />
         </button>
        <div className="flex items-center gap-3">
          <img
            src={imageError ? '/images/default-album.png' : currentSong.coverImage}
            alt={currentSong.title}
            className="w-12 h-12 rounded object-cover"
            onError={() => setImageError(true)}
          />
          <div className="flex-1 min-w-0">
            <p className="text-white font-bold text-xs truncate">{cleanTitle(currentSong.title)}</p>
            <p className="text-white/70 text-xs truncate">{currentSong.artistName}</p>
          </div>
          <div className="flex items-center gap-1">
             <Button
               variant="ghost"
               size="icon"
               onClick={togglePlay}
               className="text-white hover:bg-red-600 h-7 w-7"
             >
               {isPlaying ? <Pause className="w-4 h-4" fill="currentColor" /> : <Play className="w-4 h-4" fill="currentColor" />}
             </Button>
             <Button
               variant="ghost"
               size="icon"
               onClick={handleNext}
               className="text-white hover:bg-red-600 h-7 w-7"
             >
               <SkipForward className="w-4 h-4" />
             </Button>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`fixed bottom-0 left-0 right-0 z-50 shadow-2xl transition-all animate-in slide-in-from-bottom duration-300 ${showQueue ? 'h-auto' : ''}`}>
      {/* Minimize Button */}
      <button
        onClick={() => {
          setIsCompact(true);
          setIsCompactMode(true);
        }}
        className="absolute right-24 -top-6 z-50 bg-zinc-900 border-t border-l border-r border-white/20 px-2 py-1 rounded-t hover:bg-zinc-800 transition"
        title="Compactar player"
      >
        <ChevronDown className="w-4 h-4 text-white" />
      </button>
      
      {/* Main Player */}
      <div className="bg-gradient-to-r from-red-600 to-red-700 border-t border-white/20 px-4 py-2">
        <div className="max-w-screen-2xl mx-auto">
          <div className="flex items-center justify-between gap-4">
            {/* Song Info */}
             <div 
               className="flex items-center gap-3 w-72 cursor-pointer"
               onClick={async () => {
                 if (!currentSong) return;
                 
                 try {
                   // Fetch artist info to get slug
                   const { data: artist } = await supabase
                     .from('artists')
                     .select('slug')
                     .eq('id', currentSong.artist_id || currentSong.artistId)
                     .single();
                   
                   // Fetch album info to get slug
                   const { data: album } = await supabase
                     .from('albums')
                     .select('slug')
                     .eq('id', currentSong.album_id || currentSong.albumId)
                     .single();
                   
                   if (artist?.slug && album?.slug) {
                     navigate(`/${artist.slug}/${album.slug}`);
                   }
                 } catch (error) {
                   console.error('Error fetching slugs:', error);
                 }
               }}
             >
               <div className="relative group">
                 <img
                   src={imageError ? '/images/default-album.png' : currentSong.coverImage}
                   alt={currentSong.title}
                   className="w-11 h-11 rounded object-cover shadow-lg group-hover:shadow-xl transition-all group-hover:brightness-75"
                   onError={() => setImageError(true)}
                 />
                 <div className="absolute inset-0 bg-black/20 rounded opacity-0 group-hover:opacity-100 transition-opacity" />
               </div>
              <div className="flex-1 min-w-0">
                <p className="text-white font-bold text-sm truncate">{cleanTitle(currentSong.title)}</p>
                <p className="text-white/80 text-xs truncate">{currentSong.artistName}</p>
              </div>
              <Button
                variant="ghost"
                size="icon"
                onClick={(e) => {
                  e.stopPropagation();
                  handleFavorite();
                }}
                className="hover:bg-white/20 h-8 w-8"
              >
                <Heart
                  className={`w-4 h-4 ${
                    isFavorite ? 'fill-white text-white' : 'text-white'
                  }`}
                />
              </Button>
            </div>

            {/* Player Controls */}
            <div className="flex-1 max-w-2xl">
              <div className="flex items-center justify-center gap-3 mb-1">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={toggleShuffle}
                  className={`hover:bg-white/20 h-8 w-8 ${
                    isShuffle ? 'text-white' : 'text-white/60'
                  }`}
                >
                  <Shuffle className="w-3.5 h-3.5" />
                </Button>

                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handlePrevious}
                  className="text-white hover:bg-white/20 h-8 w-8"
                >
                  <SkipBack className="w-4 h-4" />
                </Button>

                <Button
                  onClick={togglePlay}
                  className="w-10 h-10 rounded-full bg-white hover:bg-gray-100 text-red-600 shadow-lg"
                >
                  {isPlaying ? <Pause className="w-5 h-5" fill="currentColor" /> : <Play className="w-5 h-5 ml-0.5" fill="currentColor" />}
                </Button>

                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handleNext}
                  className="text-white hover:bg-white/20 h-8 w-8"
                >
                  <SkipForward className="w-4 h-4" />
                </Button>

                <Button
                  variant="ghost"
                  size="icon"
                  onClick={toggleRepeat}
                  className={`hover:bg-white/20 h-8 w-8 ${
                    repeatMode !== 'off' ? 'text-white' : 'text-white/60'
                  }`}
                >
                  <Repeat className="w-3.5 h-3.5" />
                  {repeatMode === 'one' && (
                    <span className="absolute text-xs font-bold">1</span>
                  )}
                </Button>
              </div>

              {/* Progress Bar */}
              <div className="flex items-center gap-2">
                <span className="text-xs text-white font-medium w-10 text-right">
                  {formatDuration(Math.floor(currentTime))}
                </span>
                <Slider
                  value={[currentTime]}
                  max={duration || 100}
                  step={0.1}
                  onValueChange={(value) => seekTo(value[0])}
                  className="flex-1"
                />
                <span className="text-xs text-white font-medium w-10">
                  {formatDuration(Math.floor(duration))}
                </span>
              </div>
            </div>

            {/* Additional Controls */}
             <div className="flex items-center gap-2 w-72 justify-end">
               <Button
                 variant="ghost"
                 onClick={handleDownload}
                 className="text-white hover:bg-white/20 border border-white/30 px-3 h-8 text-xs"
               >
                 <Download className="w-3.5 h-3.5 mr-1.5" />
                 BAIXAR
               </Button>

               <Button
                 variant="ghost"
                 size="icon"
                 onClick={handleCreatePlaylist}
                 className="text-white hover:bg-white/20 h-8 w-8"
                 title="Criar playlist"
               >
                 <CreatePlaylistIcon />
               </Button>

               <Button
                 variant="ghost"
                 size="icon"
                 onClick={() => setShowQueue(!showQueue)}
                 className={`text-white hover:bg-white/20 h-8 w-8 ${showQueue ? 'bg-white/20' : ''}`}
               >
                 <List className="w-4 h-4" />
               </Button>

              <Button
                variant="ghost"
                size="icon"
                onClick={toggleMute}
                className="text-white hover:bg-white/20 h-8 w-8"
              >
                {isMuted || volume === 0 ? (
                  <VolumeX className="w-4 h-4" />
                ) : (
                  <Volume2 className="w-4 h-4" />
                )}
              </Button>

              <Slider
                value={[volume]}
                max={1}
                step={0.01}
                onValueChange={handleVolumeChange}
                className="w-20"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Queue Panel - Below Player */}
      {showQueue && (
        <div className="bg-zinc-900 border-t border-zinc-800">
          <div className="max-w-screen-2xl mx-auto">
            <div className="flex items-center justify-between px-4 py-2 border-b border-zinc-800">
              <div>
                <h3 className="text-white font-semibold text-sm">Fila de Reprodução</h3>
                <p className="text-gray-400 text-xs">{queue.length} músicas</p>
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={handleClearQueue}
                className="text-gray-400 hover:text-white hover:bg-zinc-800 h-8 px-3"
              >
                <Trash2 className="w-4 h-4 mr-2" />
                Limpar fila
              </Button>
            </div>
            <div className="overflow-x-auto overflow-y-hidden px-4 py-3">
              <div className="flex gap-3">
                {queue.map((song, index) => (
                  <div
                    key={song.id}
                    onClick={() => handlePlayFromQueue(song)}
                    className={`flex-shrink-0 flex items-center gap-3 p-2 rounded-lg cursor-pointer transition-all min-w-[220px] ${
                      currentSong.id === song.id 
                        ? 'bg-red-600/30 ring-1 ring-red-500' 
                        : 'hover:bg-zinc-800'
                    }`}
                  >
                    <img 
                      src={song.coverImage || '/images/default-album.png'} 
                      alt={song.title}
                      className="w-14 h-14 object-cover rounded"
                      onError={(e) => e.target.src = '/images/default-album.png'}
                    />
                    <div className="flex-1 min-w-0">
                      <p className="text-white text-sm font-medium truncate">{cleanTitle(song.title)}</p>
                      <p className="text-gray-400 text-xs truncate">{song.artistName}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
      
      {/* Create Playlist Dialog */}
      {createPlaylistOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl max-w-2xl w-full mx-4">
            <div className="flex items-center justify-between px-6 py-4 border-b">
              <h2 className="text-lg font-bold text-gray-900">Criar Playlist</h2>
              <button
                onClick={() => setCreatePlaylistOpen(false)}
                className="text-gray-500 hover:text-gray-700"
              >
                ✕
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 p-6">
              {/* Capa */}
              <div className="flex flex-col items-center gap-4">
                <div className="w-40 h-40 bg-red-600 rounded-lg flex items-center justify-center cursor-pointer hover:bg-red-700 transition">
                  {playlistData.cover ? (
                    <img 
                      src={URL.createObjectURL(playlistData.cover)} 
                      alt="Capa" 
                      className="w-full h-full object-cover rounded-lg"
                    />
                  ) : (
                    <div className="text-center">
                      <div className="text-white text-4xl mb-2">♫</div>
                      <p className="text-white text-sm font-medium">Adicionar capa</p>
                    </div>
                  )}
                </div>
                <label className="text-xs text-gray-600 cursor-pointer hover:text-gray-900">
                  <input
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={(e) => {
                      if (e.target.files?.[0]) {
                        setPlaylistData({...playlistData, cover: e.target.files[0]});
                      }
                    }}
                  />
                  Clique para adicionar
                </label>
              </div>

              {/* Formulário */}
              <div className="md:col-span-2 space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-900 mb-2">Título</label>
                  <input
                    type="text"
                    value={playlistData.title}
                    onChange={(e) => setPlaylistData({...playlistData, title: e.target.value})}
                    placeholder="Título da playlist"
                    maxLength={100}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-600"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-900 mb-2">Descrição</label>
                  <textarea
                    value={playlistData.description}
                    onChange={(e) => setPlaylistData({...playlistData, description: e.target.value})}
                    placeholder="Descreva sua playlist..."
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-600"
                  />
                </div>

                <div className="flex items-center justify-between">
                  <label className="text-sm font-medium text-gray-900">Privada?</label>
                  <button
                    onClick={() => setPlaylistData({...playlistData, isPublic: !playlistData.isPublic})}
                    className={`w-12 h-6 rounded-full transition-colors ${
                      playlistData.isPublic ? 'bg-gray-300' : 'bg-red-600'
                    }`}
                  >
                    <div className={`w-5 h-5 bg-white rounded-full transition-transform ${
                      playlistData.isPublic ? 'translate-x-0.5' : 'translate-x-6'
                    }`} />
                  </button>
                </div>
              </div>
            </div>

            <div className="flex justify-end gap-3 px-6 py-4 border-t">
              <button
                onClick={() => setCreatePlaylistOpen(false)}
                className="px-4 py-2 text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancelar
              </button>
              <button
                onClick={async () => {
                  if (!playlistData.title.trim()) {
                    toast({
                      title: 'Erro',
                      description: 'Digite um título',
                      variant: 'destructive'
                    });
                    return;
                  }

                  try {
                    const { data: newPlaylist } = await supabase
                      .from('playlists')
                      .insert({
                        title: playlistData.title,
                        description: playlistData.description,
                        is_public: playlistData.isPublic,
                        user_id: user.id
                      })
                      .select()
                      .single();

                    if (newPlaylist && queue.length > 0) {
                      const playlistSongs = queue.map(s => ({
                        playlist_id: newPlaylist.id,
                        song_id: s.id
                      }));
                      await supabase
                        .from('playlist_songs')
                        .insert(playlistSongs);
                    }

                    toast({
                      title: 'Sucesso',
                      description: 'Playlist criada'
                    });
                    setCreatePlaylistOpen(false);
                    setPlaylistData({
                      title: '',
                      description: '',
                      isPublic: false,
                      cover: null
                    });
                  } catch (error) {
                    toast({
                      title: 'Erro',
                      description: 'Erro ao criar playlist',
                      variant: 'destructive'
                    });
                  }
                }}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
              >
                Criar
              </button>
            </div>
          </div>
        </div>
      )}
      </div>
      );
      };

export default Player;
