import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../lib/supabaseClient';
import { useAuth } from '../../context/AuthContext';
import {
    MessageCircle, Heart, Music, Settings, Mail, LogOut,
    ChevronDown, Plus, Trash2, Eye, EyeOff, Lock, Menu, X
} from 'lucide-react';
import { Button } from '../../components/ui/button';
import { toast } from '../../hooks/use-toast';
import Header from '../../components/Layout/Header';

const UserPanelNew = () => {
    const { user, logout } = useAuth();
    const navigate = useNavigate();
    const [activeTab, setActiveTab] = useState('playlists');
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [userAvatar, setUserAvatar] = useState(null);

    // Estados para Minhas Playlists
    const [playlists, setPlaylists] = useState([]);
    const [playlistName, setPlaylistName] = useState('');
    const [playlistDescription, setPlaylistDescription] = useState('');
    const [showCreatePlaylist, setShowCreatePlaylist] = useState(false);

    // Estados para Favoritos
    const [favoriteAlbums, setFavoriteAlbums] = useState([]);
    const [favoriteSongs, setFavoriteSongs] = useState([]);

    // Estados para Configurações
    const [email, setEmail] = useState(user?.email || '');
    const [password, setPassword] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPasswords, setShowPasswords] = useState({
        current: false,
        new: false,
        confirm: false
    });

    // Carregar avatar do usuário
    useEffect(() => {
        if (user?.user_metadata?.avatar_url) {
            setUserAvatar(user.user_metadata.avatar_url);
        } else {
            setUserAvatar('/images/default-avatar.png');
        }
    }, [user]);

    // Carregar dados
    useEffect(() => {
        if (activeTab === 'playlists') {
            loadUserPlaylists();
        } else if (activeTab === 'favoritos') {
            loadFavorites();
        }
    }, [activeTab]);

    // Carregar playlists do usuário
    const loadUserPlaylists = async () => {
        try {
            setLoading(true);
            const { data, error } = await supabase
                .from('playlists')
                .select('*')
                .eq('user_id', user.id)
                .order('created_at', { ascending: false });

            if (error) throw error;
            setPlaylists(data || []);
        } catch (error) {
            console.error('Erro ao carregar playlists:', error);
            toast({
                title: 'Erro',
                description: 'Não foi possível carregar as playlists',
                variant: 'destructive'
            });
        } finally {
            setLoading(false);
        }
    };

    // Carregar favoritos
    const loadFavorites = async () => {
        try {
            setLoading(true);
            const { data: albums, error: albumError } = await supabase
                .from('favorite_albums')
                .select('*, albums(*)')
                .eq('user_id', user.id);

            const { data: songs, error: songError } = await supabase
                .from('favorite_songs')
                .select('*, songs(*)')
                .eq('user_id', user.id);

            if (albumError) throw albumError;
            if (songError) throw songError;

            setFavoriteAlbums(albums || []);
            setFavoriteSongs(songs || []);
        } catch (error) {
            console.error('Erro ao carregar favoritos:', error);
        } finally {
            setLoading(false);
        }
    };

    // Criar nova playlist
    const handleCreatePlaylist = async (e) => {
        e.preventDefault();
        if (!playlistName.trim()) {
            toast({
                title: 'Erro',
                description: 'Nome da playlist é obrigatório',
                variant: 'destructive'
            });
            return;
        }

        try {
            setLoading(true);
            const { data, error } = await supabase
                .from('playlists')
                .insert([{
                    user_id: user.id,
                    title: playlistName,
                    description: playlistDescription,
                    is_private: true,
                    slug: playlistName.toLowerCase().replace(/\s+/g, '-').replace(/[^\w-]/g, ''),
                    song_ids: []
                }])
                .select();

            if (error) throw error;

            toast({
                title: 'Sucesso',
                description: 'Playlist criada com sucesso'
            });

            setPlaylistName('');
            setPlaylistDescription('');
            setShowCreatePlaylist(false);
            loadUserPlaylists();
        } catch (error) {
            console.error('Erro ao criar playlist:', error);
            toast({
                title: 'Erro',
                description: 'Não foi possível criar a playlist',
                variant: 'destructive'
            });
        } finally {
            setLoading(false);
        }
    };

    // Deletar playlist
    const handleDeletePlaylist = async (playlistId) => {
        if (!window.confirm('Tem certeza que deseja deletar esta playlist?')) return;

        try {
            setLoading(true);
            const { error } = await supabase
                .from('playlists')
                .delete()
                .eq('id', playlistId);

            if (error) throw error;

            toast({
                title: 'Sucesso',
                description: 'Playlist deletada'
            });
            loadUserPlaylists();
        } catch (error) {
            console.error('Erro ao deletar playlist:', error);
            toast({
                title: 'Erro',
                description: 'Não foi possível deletar a playlist',
                variant: 'destructive'
            });
        } finally {
            setLoading(false);
        }
    };

    // Alternar privacidade da playlist
    const handleTogglePrivacy = async (playlistId, currentPrivacy) => {
        try {
            setLoading(true);
            const { error } = await supabase
                .from('playlists')
                .update({ is_private: !currentPrivacy })
                .eq('id', playlistId);

            if (error) throw error;

            toast({
                title: 'Sucesso',
                description: `Playlist agora é ${!currentPrivacy ? 'privada' : 'pública'}`
            });
            loadUserPlaylists();
        } catch (error) {
            console.error('Erro ao atualizar privacidade:', error);
            toast({
                title: 'Erro',
                description: 'Não foi possível atualizar a privacidade',
                variant: 'destructive'
            });
        } finally {
            setLoading(false);
        }
    };

    // Atualizar email
    const handleUpdateEmail = async (e) => {
        e.preventDefault();
        try {
            const { error } = await supabase.auth.updateUser({ email });

            if (error) throw error;

            toast({
                title: 'Sucesso',
                description: 'Email atualizado. Verifique o novo email para confirmar.'
            });
        } catch (error) {
            console.error('Erro ao atualizar email:', error);
            toast({
                title: 'Erro',
                description: error.message,
                variant: 'destructive'
            });
        }
    };

    // Atualizar senha
    const handleUpdatePassword = async (e) => {
        e.preventDefault();

        if (!password || !newPassword || !confirmPassword) {
            toast({
                title: 'Erro',
                description: 'Preencha todos os campos',
                variant: 'destructive'
            });
            return;
        }

        if (newPassword !== confirmPassword) {
            toast({
                title: 'Erro',
                description: 'As novas senhas não conferem',
                variant: 'destructive'
            });
            return;
        }

        try {
            // Verificar senha atual
            const { error: authError } = await supabase.auth.signInWithPassword({
                email: user.email,
                password
            });

            if (authError) {
                toast({
                    title: 'Erro',
                    description: 'Senha atual incorreta',
                    variant: 'destructive'
                });
                return;
            }

            // Atualizar para nova senha
            const { error: updateError } = await supabase.auth.updateUser({ password: newPassword });

            if (updateError) throw updateError;

            toast({
                title: 'Sucesso',
                description: 'Senha atualizada com sucesso'
            });

            setPassword('');
            setNewPassword('');
            setConfirmPassword('');
        } catch (error) {
            console.error('Erro ao atualizar senha:', error);
            toast({
                title: 'Erro',
                description: error.message,
                variant: 'destructive'
            });
        }
    };

    // Logout
    const handleLogout = async () => {
        try {
            await logout();
            navigate('/login');
        } catch (error) {
            console.error('Erro ao fazer logout:', error);
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 flex flex-col">
            {/* Header com Navigation */}
            <Header />

            {/* Main Content Area */}
            <div className="flex flex-1">
                {/* Sidebar Navigation - Desktop */}
                <aside className="hidden md:flex w-64 bg-white border-r border-gray-200 flex-col">
                    {/* Profile Header */}
                    <div className="p-6 border-b border-gray-200">
                        <div className="flex items-start gap-3">
                            <img
                                src={userAvatar || '/images/default-avatar.png'}
                                alt="User"
                                className="w-12 h-12 rounded-full object-cover bg-gray-200"
                                onError={(e) => e.target.src = '/images/default-avatar.png'}
                            />
                            <div className="flex-1 min-w-0">
                                <h3 className="font-semibold text-gray-900 truncate">{user?.user_metadata?.name || user?.email?.split('@')[0] || 'Usuário'}</h3>
                                <p className="text-xs text-gray-500">Conta</p>
                            </div>
                        </div>
                    </div>

                    <nav className="p-4 space-y-2 flex-1">
                        <button
                            onClick={() => setActiveTab('playlists')}
                            className={`w-full px-4 py-3 rounded-lg text-left flex items-center gap-3 transition-colors ${activeTab === 'playlists'
                                ? 'bg-red-100 text-red-700'
                                : 'text-gray-700 hover:bg-gray-100'
                                }`}
                        >
                            <Music className="w-5 h-5" />
                            <span className="font-medium">Minhas Playlists</span>
                        </button>

                        <button
                            onClick={() => setActiveTab('favoritos')}
                            className={`w-full px-4 py-3 rounded-lg text-left flex items-center gap-3 transition-colors ${activeTab === 'favoritos'
                                ? 'bg-red-100 text-red-700'
                                : 'text-gray-700 hover:bg-gray-100'
                                }`}
                        >
                            <Heart className="w-5 h-5" />
                            <span className="font-medium">Favoritos</span>
                        </button>

                        <button
                            onClick={() => setActiveTab('configuracoes')}
                            className={`w-full px-4 py-3 rounded-lg text-left flex items-center gap-3 transition-colors ${activeTab === 'configuracoes'
                                ? 'bg-red-100 text-red-700'
                                : 'text-gray-700 hover:bg-gray-100'
                                }`}
                        >
                            <Settings className="w-5 h-5" />
                            <span className="font-medium">Configurações</span>
                        </button>

                        <button
                            onClick={() => setActiveTab('suporte')}
                            className={`w-full px-4 py-3 rounded-lg text-left flex items-center gap-3 transition-colors ${activeTab === 'suporte'
                                ? 'bg-red-100 text-red-700'
                                : 'text-gray-700 hover:bg-gray-100'
                                }`}
                        >
                            <MessageCircle className="w-5 h-5" />
                            <span className="font-medium">Suporte</span>
                        </button>
                    </nav>
                </aside>

                {/* Mobile Sidebar - Overlay */}
                {isSidebarOpen && (
                    <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsSidebarOpen(false)}></div>
                )}

                <aside className={`fixed left-0 top-0 w-64 h-screen bg-white border-r border-gray-200 z-50 transform transition-transform md:hidden ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
                    }`}>
                    {/* Profile Header Mobile */}
                    <div className="p-6 border-b border-gray-200">
                        <div className="flex items-start gap-3">
                            <img
                                src={userAvatar || '/images/default-avatar.png'}
                                alt="User"
                                className="w-12 h-12 rounded-full object-cover bg-gray-200"
                                onError={(e) => e.target.src = '/images/default-avatar.png'}
                            />
                            <div className="flex-1 min-w-0">
                                <h3 className="font-semibold text-gray-900 truncate">{user?.user_metadata?.name || user?.email?.split('@')[0] || 'Usuário'}</h3>
                                <p className="text-xs text-gray-500">Conta</p>
                            </div>
                        </div>
                    </div>

                    <button
                        onClick={() => setIsSidebarOpen(false)}
                        className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-lg"
                    >
                        <X className="w-6 h-6" />
                    </button>
                    <nav className="p-4 space-y-2">
                        <button
                            onClick={() => {
                                setActiveTab('playlists');
                                setIsSidebarOpen(false);
                            }}
                            className={`w-full px-4 py-3 rounded-lg text-left flex items-center gap-3 transition-colors ${activeTab === 'playlists'
                                ? 'bg-red-100 text-red-700'
                                : 'text-gray-700 hover:bg-gray-100'
                                }`}
                        >
                            <Music className="w-5 h-5" />
                            <span className="font-medium">Minhas Playlists</span>
                        </button>

                        <button
                            onClick={() => {
                                setActiveTab('favoritos');
                                setIsSidebarOpen(false);
                            }}
                            className={`w-full px-4 py-3 rounded-lg text-left flex items-center gap-3 transition-colors ${activeTab === 'favoritos'
                                ? 'bg-red-100 text-red-700'
                                : 'text-gray-700 hover:bg-gray-100'
                                }`}
                        >
                            <Heart className="w-5 h-5" />
                            <span className="font-medium">Favoritos</span>
                        </button>

                        <button
                            onClick={() => {
                                setActiveTab('configuracoes');
                                setIsSidebarOpen(false);
                            }}
                            className={`w-full px-4 py-3 rounded-lg text-left flex items-center gap-3 transition-colors ${activeTab === 'configuracoes'
                                ? 'bg-red-100 text-red-700'
                                : 'text-gray-700 hover:bg-gray-100'
                                }`}
                        >
                            <Settings className="w-5 h-5" />
                            <span className="font-medium">Configurações</span>
                        </button>

                        <button
                            onClick={() => {
                                setActiveTab('suporte');
                                setIsSidebarOpen(false);
                            }}
                            className={`w-full px-4 py-3 rounded-lg text-left flex items-center gap-3 transition-colors ${activeTab === 'suporte'
                                ? 'bg-red-100 text-red-700'
                                : 'text-gray-700 hover:bg-gray-100'
                                }`}
                        >
                            <MessageCircle className="w-5 h-5" />
                            <span className="font-medium">Suporte</span>
                        </button>
                    </nav>
                </aside>

                {/* Main Content */}
                <main className="flex-1 p-4 md:p-8">
                    {/* Mobile Menu Button */}
                    <button
                        onClick={() => setIsSidebarOpen(true)}
                        className="md:hidden mb-4 p-2 hover:bg-gray-200 rounded-lg"
                    >
                        <Menu className="w-6 h-6" />
                    </button>
                    {/* Suporte */}
                    {activeTab === 'suporte' && (
                        <div>
                            <h2 className="text-3xl font-bold text-gray-900 mb-6">Suporte</h2>
                            <div className="bg-white rounded-lg shadow p-6">
                                <p className="text-gray-600 mb-4">
                                    Tem dúvidas ou problemas? Entre em contato conosco!
                                </p>
                                <Button
                                    onClick={() => navigate('/support')}
                                    className="bg-red-600 hover:bg-red-700 text-white"
                                >
                                    <MessageCircle className="w-4 h-4 mr-2" />
                                    Abrir Chat de Suporte
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* Minhas Playlists */}
                    {activeTab === 'playlists' && (
                        <div>
                            <div className="flex items-center justify-between mb-6">
                                <h2 className="text-3xl font-bold text-gray-900">Minhas Playlists</h2>
                                <Button
                                    onClick={() => setShowCreatePlaylist(!showCreatePlaylist)}
                                    className="bg-red-600 hover:bg-red-700 text-white"
                                >
                                    <Plus className="w-4 h-4 mr-2" />
                                    Nova Playlist
                                </Button>
                            </div>

                            {showCreatePlaylist && (
                                <div className="bg-white rounded-lg shadow p-6 mb-6">
                                    <form onSubmit={handleCreatePlaylist} className="space-y-4">
                                        <div>
                                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                                Nome da Playlist
                                            </label>
                                            <input
                                                type="text"
                                                value={playlistName}
                                                onChange={(e) => setPlaylistName(e.target.value)}
                                                placeholder="Ex: Melhores Músicas"
                                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-red-600"
                                                required
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                                Descrição (opcional)
                                            </label>
                                            <textarea
                                                value={playlistDescription}
                                                onChange={(e) => setPlaylistDescription(e.target.value)}
                                                placeholder="Descreva sua playlist"
                                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-red-600 resize-none"
                                                rows="3"
                                            />
                                        </div>
                                        <div className="flex gap-2">
                                            <Button
                                                type="submit"
                                                className="bg-red-600 hover:bg-red-700 text-white"
                                                disabled={loading}
                                            >
                                                Criar
                                            </Button>
                                            <Button
                                                type="button"
                                                variant="outline"
                                                onClick={() => setShowCreatePlaylist(false)}
                                            >
                                                Cancelar
                                            </Button>
                                        </div>
                                    </form>
                                </div>
                            )}

                            {loading ? (
                                <div className="text-center py-8">
                                    <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-red-600"></div>
                                </div>
                            ) : playlists.length === 0 ? (
                                <div className="bg-white rounded-lg shadow p-12 text-center">
                                    <Music className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                                    <p className="text-gray-600">Nenhuma playlist criada ainda</p>
                                </div>
                            ) : (
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                    {playlists.map(playlist => (
                                        <div key={playlist.id} className="bg-white rounded-lg shadow overflow-hidden hover:shadow-lg transition-shadow">
                                            <div className="p-4">
                                                <h3 className="font-semibold text-gray-900 mb-2 truncate">
                                                    {playlist.title}
                                                </h3>
                                                <p className="text-sm text-gray-600 mb-4 line-clamp-2">
                                                    {playlist.description || 'Sem descrição'}
                                                </p>
                                                <div className="flex items-center gap-2 mb-4 text-xs text-gray-500">
                                                    <Music className="w-4 h-4" />
                                                    <span>{playlist.song_ids?.length || 0} músicas</span>
                                                </div>
                                                <div className="flex gap-2">
                                                    <Button
                                                        onClick={() => handleTogglePrivacy(playlist.id, playlist.is_private)}
                                                        variant="outline"
                                                        size="sm"
                                                        className="flex-1"
                                                    >
                                                        {playlist.is_private ? (
                                                            <>
                                                                <Lock className="w-4 h-4 mr-1" />
                                                                Privada
                                                            </>
                                                        ) : (
                                                            <>
                                                                <Eye className="w-4 h-4 mr-1" />
                                                                Pública
                                                            </>
                                                        )}
                                                    </Button>
                                                    <Button
                                                        onClick={() => navigate(`/playlist/${playlist.slug || playlist.id}`)}
                                                        variant="outline"
                                                        size="sm"
                                                    >
                                                        Ver
                                                    </Button>
                                                    <Button
                                                        onClick={() => handleDeletePlaylist(playlist.id)}
                                                        variant="outline"
                                                        size="sm"
                                                        className="text-red-600 hover:bg-red-50"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </Button>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {/* Favoritos */}
                    {activeTab === 'favoritos' && (
                        <div>
                            <h2 className="text-3xl font-bold text-gray-900 mb-6">Favoritos</h2>

                            <div className="space-y-8">
                                {/* Álbuns Favoritos */}
                                <div>
                                    <h3 className="text-xl font-semibold text-gray-900 mb-4">
                                        Álbuns Favoritos ({favoriteAlbums.length})
                                    </h3>
                                    {favoriteAlbums.length === 0 ? (
                                        <div className="bg-white rounded-lg shadow p-8 text-center text-gray-500">
                                            Nenhum álbum favoritado
                                        </div>
                                    ) : (
                                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                                            {favoriteAlbums.map(fav => (
                                                <div
                                                    key={fav.id}
                                                    onClick={() => navigate(`/${fav.albums.artist_id}/${fav.albums.slug}`)}
                                                    className="bg-white rounded-lg shadow p-4 cursor-pointer hover:shadow-lg transition-shadow"
                                                >
                                                    <img
                                                        src={fav.albums.cover_url || '/placeholder-album.jpg'}
                                                        alt={fav.albums.title}
                                                        className="w-full aspect-square object-cover rounded mb-2"
                                                    />
                                                    <p className="font-medium text-sm text-gray-900 truncate">
                                                        {fav.albums.title}
                                                    </p>
                                                    <p className="text-xs text-gray-600 truncate">
                                                        {fav.albums.artist_name}
                                                    </p>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>

                                {/* Músicas Favoritas */}
                                <div>
                                    <h3 className="text-xl font-semibold text-gray-900 mb-4">
                                        Músicas Favoritas ({favoriteSongs.length})
                                    </h3>
                                    {favoriteSongs.length === 0 ? (
                                        <div className="bg-white rounded-lg shadow p-8 text-center text-gray-500">
                                            Nenhuma música favoritada
                                        </div>
                                    ) : (
                                        <div className="bg-white rounded-lg shadow overflow-hidden">
                                            {favoriteSongs.map((fav, index) => (
                                                <div
                                                    key={fav.id}
                                                    className="px-4 py-3 border-b hover:bg-gray-50 transition-colors flex items-center gap-4"
                                                >
                                                    <span className="text-gray-500 font-medium w-8">
                                                        {index + 1}
                                                    </span>
                                                    <img
                                                        src={fav.songs.cover_url || '/placeholder-album.jpg'}
                                                        alt={fav.songs.title}
                                                        className="w-10 h-10 rounded object-cover"
                                                    />
                                                    <div className="flex-1 min-w-0">
                                                        <p className="font-medium text-gray-900 truncate">
                                                            {fav.songs.title}
                                                        </p>
                                                        <p className="text-sm text-gray-600 truncate">
                                                            {fav.songs.artist_name}
                                                        </p>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Configurações */}
                    {activeTab === 'configuracoes' && (
                        <div>
                            <h2 className="text-3xl font-bold text-gray-900 mb-6">Configurações</h2>

                            <div className="max-w-2xl space-y-6">
                                {/* Atualizar Email */}
                                <div className="bg-white rounded-lg shadow p-6">
                                    <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
                                        <Mail className="w-5 h-5 text-red-600" />
                                        Email
                                    </h3>
                                    <form onSubmit={handleUpdateEmail} className="space-y-4">
                                        <div>
                                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                                Email Atual
                                            </label>
                                            <input
                                                type="email"
                                                value={email}
                                                onChange={(e) => setEmail(e.target.value)}
                                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-red-600"
                                            />
                                        </div>
                                        <Button
                                            type="submit"
                                            className="bg-red-600 hover:bg-red-700 text-white"
                                        >
                                            Atualizar Email
                                        </Button>
                                        <p className="text-xs text-gray-500">
                                            Um link de confirmação será enviado para o novo email.
                                        </p>
                                    </form>
                                </div>

                                {/* Atualizar Senha */}
                                <div className="bg-white rounded-lg shadow p-6">
                                    <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
                                        <Lock className="w-5 h-5 text-red-600" />
                                        Alterar Senha
                                    </h3>
                                    <form onSubmit={handleUpdatePassword} className="space-y-4">
                                        <div>
                                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                                Senha Atual
                                            </label>
                                            <div className="relative">
                                                <input
                                                    type={showPasswords.current ? 'text' : 'password'}
                                                    value={password}
                                                    onChange={(e) => setPassword(e.target.value)}
                                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-red-600"
                                                />
                                                <button
                                                    type="button"
                                                    onClick={() => setShowPasswords(p => ({ ...p, current: !p.current }))}
                                                    className="absolute right-3 top-2.5 text-gray-500"
                                                >
                                                    {showPasswords.current ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                </button>
                                            </div>
                                        </div>

                                        <div>
                                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                                Nova Senha
                                            </label>
                                            <div className="relative">
                                                <input
                                                    type={showPasswords.new ? 'text' : 'password'}
                                                    value={newPassword}
                                                    onChange={(e) => setNewPassword(e.target.value)}
                                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-red-600"
                                                />
                                                <button
                                                    type="button"
                                                    onClick={() => setShowPasswords(p => ({ ...p, new: !p.new }))}
                                                    className="absolute right-3 top-2.5 text-gray-500"
                                                >
                                                    {showPasswords.new ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                </button>
                                            </div>
                                        </div>

                                        <div>
                                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                                Confirmar Nova Senha
                                            </label>
                                            <div className="relative">
                                                <input
                                                    type={showPasswords.confirm ? 'text' : 'password'}
                                                    value={confirmPassword}
                                                    onChange={(e) => setConfirmPassword(e.target.value)}
                                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-red-600"
                                                />
                                                <button
                                                    type="button"
                                                    onClick={() => setShowPasswords(p => ({ ...p, confirm: !p.confirm }))}
                                                    className="absolute right-3 top-2.5 text-gray-500"
                                                >
                                                    {showPasswords.confirm ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                </button>
                                            </div>
                                        </div>

                                        <Button
                                            type="submit"
                                            className="bg-red-600 hover:bg-red-700 text-white"
                                        >
                                            Atualizar Senha
                                        </Button>
                                    </form>
                                </div>
                            </div>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
};

export default UserPanelNew;
