import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../lib/supabaseClient';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Label } from '../../components/ui/label';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../../components/ui/card';
import { Lock, Music } from 'lucide-react';
import { toast } from '../../hooks/use-toast';

const AdminLogin = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      toast({
        title: 'Erro',
        description: 'Por favor, insira email e senha',
        variant: 'destructive'
      });
      return;
    }

    setIsLoading(true);
    try {
      // Fazer login normal
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password
      });

      if (error) {
        toast({
          title: 'Erro',
          description: error.message || 'Email ou senha incorretos',
          variant: 'destructive'
        });
        setIsLoading(false);
        return;
      }

      // Verificar se é admin
      const { data: adminData, error: adminError } = await supabase
        .from('admin_users')
        .select('*')
        .eq('id', data.user.id)
        .maybeSingle();

      if (!adminData) {
        // Fazer logout se não for admin
        await supabase.auth.signOut();
        toast({
          title: 'Acesso Negado',
          description: 'Esta conta não tem permissão de administrador',
          variant: 'destructive'
        });
        setIsLoading(false);
        return;
      }

      toast({
        title: 'Login realizado!',
        description: 'Bem-vindo ao painel admin'
      });

      navigate('/admin');
    } catch (error) {
      toast({
        title: 'Erro',
        description: 'Ocorreu um erro ao fazer login',
        variant: 'destructive'
      });
    }
    setIsLoading(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-red-600 to-red-700 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="flex items-center justify-center space-x-2 mb-4">
            <Lock className="w-12 h-12 text-white" />
            <h1 className="text-4xl font-bold text-white">RedMusic</h1>
          </div>
          <p className="text-red-100">Painel de Administrador</p>
        </div>

        <Card className="bg-white shadow-2xl">
          <CardHeader>
            <CardTitle className="text-black">Acesso Admin</CardTitle>
            <CardDescription className="text-gray-600">
              Apenas administradores podem acessar este painel
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleLogin} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="email" className="text-black font-semibold">E-mail de Admin</Label>
                <Input
                  id="email"
                  type="email"
                  placeholder="admin@email.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="bg-gray-50 border-gray-300 text-black"
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="password" className="text-black font-semibold">Senha</Label>
                <Input
                  id="password"
                  type="password"
                  placeholder="Sua senha"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="bg-gray-50 border-gray-300 text-black"
                  required
                />
              </div>

              <Button 
                type="submit" 
                className="w-full bg-red-600 hover:bg-red-700 text-white font-semibold"
                disabled={isLoading}
              >
                <Lock className="w-4 h-4 mr-2" />
                {isLoading ? 'Autenticando...' : 'Entrar no Painel Admin'}
              </Button>
            </form>

            <div className="mt-6 p-4 bg-red-50 border border-red-200 rounded-lg text-sm text-red-800">
              <p className="font-semibold mb-2">⚠️ Atenção</p>
              <p>Este é um painel restrito. Apenas contas autorizadas podem acessar.</p>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default AdminLogin;
